FUNCTION_BLOCK FB_S14
VAR_INPUT
    Pressure : REAL;
    PumpEnable : BOOL;
    ResetBtn : BOOL;
END_VAR
VAR_OUTPUT
    LowPump : BOOL;
    HighPump : BOOL;
    ReliefValve : BOOL;
    AlarmLamp : BOOL;
    Status : WORD;
END_VAR
VAR
    HighPumpLatched : BOOL := FALSE;
    LowPumpLatched : BOOL := FALSE;
    ReliefValveLatched : BOOL := FALSE;
    ResetBtnLast : BOOL := FALSE;
    PendingReset : BOOL := FALSE;
    FirstScan : BOOL := TRUE;
    sensorInvalid : BOOL;
    ResetEdge : BOOL;
END_VAR

(* 复位按钮上升沿检测 *)
ResetEdge := ResetBtn AND NOT ResetBtnLast;

IF FirstScan THEN
    (* 上电首周期初态：不加载、无报警 *)
    LowPump := FALSE;
    HighPump := FALSE;
    ReliefValve := FALSE;
    AlarmLamp := FALSE;
    Status := 16#0000;
    HighPumpLatched := FALSE;
    LowPumpLatched := FALSE;
    ReliefValveLatched := FALSE;
    PendingReset := FALSE;
    FirstScan := FALSE;
    ResetBtnLast := ResetBtn;
ELSE
    (* 传感器越界检测：断线/短路 *)
    sensorInvalid := (Pressure < 0.5) OR (Pressure > 250.0);

    IF sensorInvalid THEN
        (* 传感器故障：立即停泵报警，记录待复位 *)
        PendingReset := TRUE;
        AlarmLamp := TRUE;
        Status := 16#8D01;
        LowPump := FALSE;
        HighPump := FALSE;
        LowPumpLatched := FALSE;
        HighPumpLatched := FALSE;

        (* 卸荷阀按压力滞回，过压时打开 *)
        IF Pressure > 160.0 THEN
            ReliefValveLatched := TRUE;
        ELSIF Pressure < 150.0 THEN
            ReliefValveLatched := FALSE;
        END_IF;
        ReliefValve := ReliefValveLatched;

        (* 确保互斥 *)
        IF ReliefValve THEN
            LowPump := FALSE;
            HighPump := FALSE;
        END_IF;

    ELSIF PendingReset THEN
        (* 故障消失后待复位：泵停、报警保持、Status=8D02 *)
        AlarmLamp := TRUE;
        Status := 16#8D02;
        LowPump := FALSE;
        HighPump := FALSE;
        LowPumpLatched := FALSE;
        HighPumpLatched := FALSE;

        (* 卸荷阀仍按压力滞回 *)
        IF Pressure > 160.0 THEN
            ReliefValveLatched := TRUE;
        ELSIF Pressure < 150.0 THEN
            ReliefValveLatched := FALSE;
        END_IF;
        ReliefValve := ReliefValveLatched;

        IF ReliefValve THEN
            LowPump := FALSE;
            HighPump := FALSE;
        END_IF;

        (* ResetBtn 上升沿复位 *)
        IF ResetEdge THEN
            PendingReset := FALSE;
            AlarmLamp := FALSE;
            Status := 16#0000;
            (* 本周期不加载，下一周期恢复正常 *)
        END_IF;

    ELSE
        (* 正常状态 *)
        AlarmLamp := FALSE;
        Status := 16#0000;

        (* 卸荷阀滞回：>160 开，<150 关，150~160 保持 *)
        IF Pressure > 160.0 THEN
            ReliefValveLatched := TRUE;
        ELSIF Pressure < 150.0 THEN
            ReliefValveLatched := FALSE;
        END_IF;
        ReliefValve := ReliefValveLatched;

        IF ReliefValve THEN
            (* 卸荷与泵互斥：卸荷时强制停泵并清除泵锁存 *)
            LowPump := FALSE;
            HighPump := FALSE;
            LowPumpLatched := FALSE;
            HighPumpLatched := FALSE;
        ELSE
            IF PumpEnable THEN
                (* 高压泵滞回：>=140 投入；<100 断开；100~140 保持 *)
                IF Pressure >= 140.0 THEN
                    HighPumpLatched := TRUE;
                ELSIF Pressure < 100.0 THEN
                    HighPumpLatched := FALSE;
                END_IF;

                (* 低压泵：<120 启动；启动后保持，直至卸荷/禁用/故障 *)
                IF Pressure < 120.0 THEN
                    LowPumpLatched := TRUE;
                END_IF;

                LowPump := LowPumpLatched;
                HighPump := HighPumpLatched;
            ELSE
                (* 未允许加载：停泵并清除锁存 *)
                LowPump := FALSE;
                HighPump := FALSE;
                LowPumpLatched := FALSE;
                HighPumpLatched := FALSE;
            END_IF;
        END_IF;
    END_IF;

    ResetBtnLast := ResetBtn;
END_IF;

(* 最终安全互斥：卸荷阀与泵不得同时为 TRUE *)
IF ReliefValve THEN
    LowPump := FALSE;
    HighPump := FALSE;
END_IF;

END_FUNCTION_BLOCK
